const OFFSETS = [-1, 0, 1];

const cellKey = ([x, y]: Cell): string => `${x},${y}`;

const candidateCells = (liveCells: Cell[]): Cell[] => {
  const candidatesByKey = new Map<string, Cell>();

  for (const [x, y] of liveCells) {
    for (const offsetX of OFFSETS) {
      for (const offsetY of OFFSETS) {
        const candidate: Cell = [x + offsetX, y + offsetY];
        candidatesByKey.set(cellKey(candidate), candidate);
      }
    }
  }

  return [...candidatesByKey.values()];
};

export function nextGeneration(liveCells: Cell[]): Cell[] {
  return candidateCells(liveCells).filter((cell) =>
    isAliveNextGeneration(cell, liveCells),
  );
}

